{
 "doc1_consumer_complaint": {
  "submitted": "2026-08-19",
  "consumer": "Imani Castellane-Brooks",
  "text": "On August 4 a debt collector called my job at Harbor Point Logistics and talked to my supervisor, Dennis. Dennis pulled me aside and said the man told him I owed money on a credit card and that they'd be garnishing my paycheck soon. I was humiliated in front of my team. I have never been sued over this card. I want this company to stop calling my workplace and I want this account deleted from my credit report."
 },
 "doc2_company_response": {
  "date": "2026-09-02",
  "from": "Ridgeline Recovery Partners, Compliance",
  "text": "Ridgeline placed a single location call to the consumer's employer on 08/04/2026 to confirm place of employment. Our agent did not disclose the existence of any debt, and no statement regarding garnishment was made. We have coded the employer's number Do Not Call. The account remains open and accurately reported."
 },
 "doc3_qa_call_review": {
  "reviewed": "2026-09-10",
  "reviewer": "M. Oyelaran, Quality Assurance",
  "call": "2026-08-04 10:22 a.m., outbound to Harbor Point Logistics main line, agent D. Fairbanks",
  "transcript": [
   {
    "speaker": "Agent",
    "text": "Hi, this is Dale with Ridgeline Recovery Partners. I'm trying to reach Imani Castellane-Brooks about a past-due account. Does she still work there?"
   },
   {
    "speaker": "Receptionist",
    "text": "Let me get her supervisor. One sec."
   },
   {
    "speaker": "Supervisor (Dennis Ruiz)",
    "text": "This is Dennis. She works here, yeah. Is she in some kind of trouble?"
   },
   {
    "speaker": "Agent",
    "text": "I can't get into details, but she needs to call us back about this balance before it goes any further. Can you give her our number, 888-555-0164?"
   },
   {
    "speaker": "Supervisor (Dennis Ruiz)",
    "text": "Are you guys going to take it out of her check? We've had that happen with other employees."
   },
   {
    "speaker": "Agent",
    "text": "That's not something I can discuss. Just have her call us."
   }
  ],
  "finding": "Agent volunteered the agency name and referred to a 'past-due account' and 'this balance' to a third party. Call does not meet the LOC-1 script. Severity: High."
 },
 "doc4_policy_LOC_1": "A call to a third party to obtain location information may only: (1) give the caller's own name; (2) state that the caller is confirming or correcting location information about the consumer; (3) name the agency only if the third party expressly asks for it. The caller must never state or imply that the consumer owes a debt and must not mention an account, balance or collection."
}
